#!/usr/bin/env python3
"""Patches the Gradle file generated by `flutter create` for TapCast.

Idempotent: running it twice leaves the file unchanged. Requires the Kotlin DSL
build file (`android/app/build.gradle.kts`), which Flutter 3.29+ generates.

Usage: python3 tool/patch_gradle.py [path/to/android/app/build.gradle.kts]
"""
import re
import sys
from pathlib import Path

MARKER = "// --- TapCast patch ---"
APP_ID = "com.tapcast.app"
YTDLP_VERSION = "0.18.1"  # first youtubedl-android release with QuickJS (needed for YouTube)

SIGNING_HEADER = f'''{MARKER}
import java.util.Properties

val keystoreProps = Properties().apply {{
    val f = rootProject.file("key.properties")
    if (f.exists()) f.inputStream().use {{ load(it) }}
}}
'''

SIGNING_CONFIGS = '''
    signingConfigs {
        create("release") {
            if (keystoreProps.getProperty("storeFile") != null) {
                storeFile = rootProject.file(keystoreProps.getProperty("storeFile"))
                storePassword = keystoreProps.getProperty("storePassword")
                keyAlias = keystoreProps.getProperty("keyAlias")
                keyPassword = keystoreProps.getProperty("keyPassword")
            }
        }
    }
'''

PACKAGING = '''
    packaging {
        jniLibs {
            // yt-dlp / ffmpeg binaries are executed from the extracted native lib dir.
            useLegacyPackaging = true
        }
    }

    lint {
        // The release lint step crashed the CI build; lint is not needed to produce the APK.
        checkReleaseBuilds = false
        abortOnError = false
    }
'''

DEPENDENCIES = f'''
dependencies {{
    implementation("io.github.junkfood02.youtubedl-android:library:{YTDLP_VERSION}")
    implementation("io.github.junkfood02.youtubedl-android:ffmpeg:{YTDLP_VERSION}")
    implementation("androidx.documentfile:documentfile:1.0.1")
    implementation("androidx.core:core-ktx:1.13.1")
}}
'''


def sub_once(pattern: str, repl: str, text: str, what: str) -> str:
    new, n = re.subn(pattern, repl, text, count=1, flags=re.MULTILINE)
    if n != 1:
        sys.exit(f"patch_gradle: could not find {what}. Was the file generated by Flutter 3.29 or newer?")
    return new


def patch(text: str) -> str:
    if MARKER in text:
        return text

    text = sub_once(r'namespace\s*=\s*"[^"]*"', f'namespace = "{APP_ID}"', text, "namespace")
    text = sub_once(r'applicationId\s*=\s*"[^"]*"', f'applicationId = "{APP_ID}"', text, "applicationId")
    text = sub_once(r"minSdk\s*=\s*flutter\.minSdkVersion", "minSdk = 29", text, "minSdk")

    # ABI filters inside defaultConfig (right after minSdk).
    text = sub_once(
        r"(minSdk = 29\n)",
                r'\1',
        text,
        "defaultConfig",
    )

    # Release signing from android/key.properties; falls back to debug keys when absent.
    text = sub_once(
        r'signingConfig\s*=\s*signingConfigs\.getByName\("debug"\)',
        'signingConfig = if (keystoreProps.getProperty("storeFile") != null) '
                'signingConfigs.getByName("release") else signingConfigs.getByName("debug")\n'
        '            isMinifyEnabled = false\n'
        '            isShrinkResources = false',
        text,
        "release signingConfig",
    )

    # signingConfigs + packaging go right before buildTypes.
    text = sub_once(r"(\n    buildTypes \{)", SIGNING_CONFIGS + PACKAGING + r"\1", text, "buildTypes")

    # Dependencies block goes before the `flutter { ... }` block.
    text = sub_once(r"(\nflutter \{)", DEPENDENCIES + r"\1", text, "flutter block")

    return SIGNING_HEADER + "\n" + text


def main() -> None:
    path = Path(sys.argv[1] if len(sys.argv) > 1 else "android/app/build.gradle.kts")
    if not path.exists():
        sys.exit(f"patch_gradle: {path} not found. Run `flutter create` first (see setup.sh).")
    original = path.read_text()
    patched = patch(original)
    if patched == original:
        print("build.gradle.kts already patched")
        return
    path.write_text(patched)
    print(f"patched {path}")


if __name__ == "__main__":
    main()
